    const keys=['segments','tax','netInterest','depreciation','workingCapital','capexStart','capexEnd','leaseStart','leaseEnd','discount','terminal'];if(m.consolidationPath)keys.push('eliminationStart','eliminationEnd','otherProfitStart','otherProfitEnd','minority');if(m.normalizationPath)keys.push('excludedProfitStart','excludedProfitEnd');if(m.unallocatedPath)keys.push('corporateStart','corporateEnd');if(m.reservePath)keys.push('warrantyAccrual','warrantyUseStart','warrantyUseEnd');if(m.grossProfitPath)keys.push('researchStart','researchEnd','sellingStart','sellingEnd','otherOperatingStart','otherOperatingEnd','minority');
    if(m.minorityPath&&!keys.includes('minority'))keys.push('minority');
