    if(m.equityInvestmentPath&&a.equityInvestmentValue!==null&&(typeof a.equityInvestmentValue!=='number'||!Number.isFinite(a.equityInvestmentValue)||a.equityInvestmentValue<0))throw Error('투자 가치는 미평가 빈칸 또는 0 이상의 명시적 가정이어야 합니다.');
    if('minority' in a&&(a.minority<0||a.minority>1))throw Error('비지배 배분은 매출의 0–100% 범위입니다.');
