    if(['depreciation','capexStart','capexEnd','leaseStart','leaseEnd'].some(k=>a[k]<0||a[k]>1)||a.workingCapital<-.5||a.workingCapital>1||a.netInterest<-.2||a.netInterest>.2)throw Error('재투자·운전자본 가정 범위를 확인하세요.');
    if(m.normalizationPath&&['excludedProfitStart','excludedProfitEnd'].some(k=>a[k]<0||a[k]>.5))throw Error('제외할 영업이익은 매출의 0–50% 범위입니다.');
